-- Where a build opens (docs/plan.md §1.172; owner, 2026-11-21): `build.flow` is `phases` (its build
-- page, through intake, fit-gap, draft and the tests) or `describe` (started on the lab's Describe
-- it: it opens in the one-screen builder). One column with a default and its check, so the previous
-- Worker keeps working: it never reads or writes it, and every build it makes is `phases`. No
-- backfill: which builds before this one started on Describe isn't stored anywhere, and guessing by
-- date would be wrong wherever the old New was still in use. Generated by drizzle-kit. Named 0073
-- after 0072.
ALTER TABLE "build" ADD COLUMN "flow" text DEFAULT 'phases' NOT NULL;--> statement-breakpoint
ALTER TABLE "build" ADD CONSTRAINT "build_flow_check" CHECK ("build"."flow" in ('phases', 'describe'));
